<body>
    <script id="yaml-data-source" type="text/yaml">$1</script>
    <div id="status-container" class="status-block-root"></div>

    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const triggerQuickReply = (text) => {
                if (!text || text.trim().length === 0) return;
                typeof triggerSlash === 'function' ? triggerSlash(`/send ${text}|/trigger`) : console.log('SillyTavern [dev]:', text);
            };
            new StatusRenderer('yaml-data-source', 'status-container', triggerQuickReply).init();
        });

        class StatusRenderer {
            constructor(sourceId, containerId, quickReplyHandler) {
                this.source = document.getElementById(sourceId);
                this.container = document.getElementById(containerId);
                this.quickReply = quickReplyHandler;
                this.data = null;
            }

            init() {
                try {
                    if (!this.source || !this.source.textContent.trim()) throw new Error('数据源未找到或为空。');
                    this.data = jsyaml.load(this.source.textContent);
                    const rootKey = Object.keys(this.data)[0];
                    this.render(this.data[rootKey], rootKey);
                    this.initEventListeners();
                } catch (e) {
                    this.container.innerHTML = `<div class="theme-dark rounded-2xl shadow-lg w-full p-4 text-red-400">渲染失败: ${e.message}</div>`;
                    console.error(e);
                }
            }

            findField(obj, keywords) {
                if (!obj) return [null, null];
                const key = Object.keys(obj).find(k => keywords.some(kw => k.toLowerCase().includes(kw)));
                return key ? [key, obj[key]] : [null, null];
            }

            cleanText(text) { return text ? text.toString().replace(/[\p{Emoji_Presentation}]/gu, '').trim() : ''; }

            render(data, title) {
                const [ , envInfo] = this.findField(data, ['环境']);
                const [ , liveData] = this.findField(data, ['直播数据']);
                const [ , liveGoal] = this.findField(data, ['直播目标']);
                const [ , characters] = this.findField(data, ['人物']);
                const [ , actions] = this.findField(data, ['行动选项']);

                let characterHTML = characters.map(charWrapper => this.renderCharacter(Object.values(charWrapper)[0])).join('');

                this.container.innerHTML = `
                    <div id="status-block-body" class="status-block-body">
                        <header class="status-block-header">
                            <div>
                                <h1 class="text-xl font-bold text-main glow-blue">${title}</h1>
                                ${this.renderEnv(envInfo)}
                            </div>
                            <div class="flex items-center gap-x-3">
                                ${this.renderLiveStatus(liveData)}
                                <button id="theme-toggle-btn" class="text-lg text-secondary" title="切换模式"></button>
                            </div>
                        </header>

                        <section class="status-block-section grid grid-cols-1 md:grid-cols-2 gap-4">
                            ${this.renderLiveData(liveData)}
                            ${this.renderLiveGoal(liveGoal)}
                        </section>

                        <section class="status-block-section !border-b-0">
                            <details id="actors-details" class="w-full group">
                                <summary class="font-bold text-main flex justify-between items-center cursor-pointer list-none -mx-4 -my-4 p-4">
                                    <span>出场人物</span>
                                    <i class="fa-solid fa-chevron-down text-link transition-transform duration-300 group-open:rotate-180"></i>
                                </summary>
                                <div class="mt-4 grid grid-cols-1 ${characterHTML.length > 0 && characters.length > 1 ? 'md:grid-cols-2' : ''} gap-4">
                                    ${characterHTML}
                                </div>
                            </details>
                        </section>

                        ${this.renderActions(actions)}
                    </div>`;
            }

            initEventListeners() {
                // Theme switcher
                const themeBtn = document.getElementById('theme-toggle-btn');
                const body = document.getElementById('status-block-body');
                const savedTheme = localStorage.getItem('statusBarTheme') || 'dark';

                const applyTheme = (theme) => {
                    body.classList.remove('theme-dark', 'theme-light');
                    body.classList.add(`theme-${theme}`);
                    themeBtn.innerHTML = theme === 'dark' ? '<i class="fa-solid fa-sun"></i>' : '<i class="fa-solid fa-moon"></i>';
                    localStorage.setItem('statusBarTheme', theme);
                };

                themeBtn.addEventListener('click', () => {
                    const newTheme = body.classList.contains('theme-dark') ? 'light' : 'dark';
                    applyTheme(newTheme);
                });
                applyTheme(savedTheme);

                // Collapsible actors
                const details = document.getElementById('actors-details');
                details.addEventListener('toggle', () => localStorage.setItem('actorsCollapsed', details.open));
                details.open = localStorage.getItem('actorsCollapsed') !== 'false';

                // Action options
                this.container.querySelector('#options-list')?.addEventListener('click', (e) => {
                    const button = e.target.closest('button');
                    if (button) {
                        this.quickReply(button.textContent.trim());
                        button.classList.add('bg-blue-400/20');
                        setTimeout(() => button.classList.remove('bg-blue-400/20'), 300);
                    }
                });
            }

            renderEnv(env) {
                if (!env) return '';
                const [, time] = this.findField(env, ['时间']);
                const [, loc] = this.findField(env, ['地点']);
                return `<div class="text-xs text-secondary flex items-center flex-wrap gap-x-3 mt-1"><span>${time || ''}</span><span>${loc || ''}</span></div>`;
            }

            renderLiveStatus(live) {
                const [, status] = this.findField(live, ['状态']);
                if(!status || !status.includes('LIVE')) return '';
                return `<div class="flex items-center space-x-2 font-bold glow-red flex-shrink-0"><i class="fa-solid fa-tower-broadcast animate-pulse"></i><span>${this.cleanText(status)}</span></div>`;
            }

            renderLiveData(live) {
                if (!live) return '';
                const [, users] = this.findField(live, ['人数']);
                const [, pop] = this.findField(live, ['热度']);
                const [, danmaku] = this.findField(live, ['弹幕']);
                const danmakuHTML = danmaku.map(d => `<div class="text-xs break-words">${d}</div>`).join('');
                return `<div>
                    <div class="flex items-center justify-between text-sm text-secondary mb-2 flex-wrap gap-2"><span>${users || '🔥 0人'}</span><span>${pop || '💰 0元'}</span></div>
                    <div class="danmaku-bg p-2 rounded-lg h-24 overflow-y-auto space-y-1.5 text-secondary styled-scrollbar">${danmakuHTML}</div>
                </div>`;
            }

            renderLiveGoal(goal) {
                if (!goal) return '';
                const [, currentGoal] = this.findField(goal, ['当前目标']);
                const [, progress] = this.findField(goal, ['进度']);
                const [, condition] = this.findField(goal, ['解锁条件']);
                const progressMatch = this.cleanText(progress).match(/(\d+)\/(\d+)/);
                const progressValue = progressMatch ? (parseInt(progressMatch[1]) / parseInt(progressMatch[2])) * 100 : 0;
                return `<div>
                    <div class="text-sm text-main mb-1 break-words">${currentGoal || ''}</div>
                    <div class="text-xs text-secondary mb-2 break-words">${condition || ''}</div>
                    <div class="progress-container h-2.5 rounded-full overflow-hidden border">${progressValue > 0 ? `<div class="progress-bar h-full rounded-full" style="width: ${progressValue}%"></div>` : ''}</div>
                    <div class="text-center text-xs text-link mt-1 font-mono">${this.cleanText(progress) || '0/0'}</div>
                </div>`;
            }

            renderCharacter(char) {
                if (!char) return '';
                const [ , name] = this.findField(char, ['名字']);
                const emoji = (name || '').match(/[\p{Emoji_Presentation}]/gu)?.[0] || '👤';
                const attributes = Object.entries(char).filter(([key]) => !['名字'].some(kw => key.toLowerCase().includes(kw))).map(([key, value]) => {
                    let valHTML = (typeof value === 'object' && value !== null)
                        ? `<ul class="pl-3 mt-1 space-y-1">${Object.entries(value).map(([sk, sv]) => `<li><span class="text-secondary">${sk}:</span> <span class="text-main break-words">${this.cleanText(sv)}</span></li>`).join('')}</ul>`
                        : `<span class="text-main break-words">${this.cleanText(value)}</span>`;
                    return `<li><strong class="text-link">${key}:</strong> ${valHTML}</li>`;
                }).join('');
                return `<div class="card p-3 rounded-lg theme-transition"><h3 class="font-bold text-main mb-2 pb-2 border-b theme-transition break-words">${emoji} ${this.cleanText(name)}</h3><ul class="text-sm space-y-2">${attributes}</ul></div>`;
            }

            renderActions(actions) {
                if (!actions) return '';
                const [, owner] = this.findField(actions, ['名字']);
                const [, options] = this.findField(actions, ['选项']);
                if (!options || !Array.isArray(options)) return '';
                const optionsHTML = options.map(opt => `<button class="action-btn w-full text-left p-3 rounded-lg theme-transition border border-transparent"><span class="text-main break-words">${opt}</span></button>`).join('');
                return `<div class="p-4 border-t theme-transition"><h3 class="text-main font-bold mb-3">${this.cleanText(owner) || '你的'} 行动选项:</h3><div id="options-list" class="space-y-2">${optionsHTML}</div></div>`;
            }
        }
    </script>
</body>
</html>
